        IReadOnlyList<RecipeIngredient>? ingredients = new List<RecipeIngredient>();
        _serviceMock
            .Setup(s => s.GetUnresolvedIngredientsAsync(recipeId, It.IsAny<CancellationToken>()))
            .ReturnsAsync(ingredients);

