        var ingredientId = Guid.NewGuid();
        var request = new ResolveContainerRequest { Quantity = 14.5m, UomId = Guid.NewGuid() };
        var ingredient = BuildResolvedIngredient(recipeId, ingredientId);
        _serviceMock
