        foreach (var (ingredientId, qty, uomId) in ingredientLines)
        {
            _dbContext.RecipeIngredients.Add(new RecipeIngredient
            {
                CanonicalIngredientId = ingredientId,
                Id = Guid.NewGuid(),
                IsContainerResolved = true,
                Quantity = qty,
                RecipeId = recipe.Id,
                UomId = uomId
            });
        }
        _dbContext.SaveChanges();
        return recipe;
    }

